import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import { build } from "esbuild";
import prettier from "prettier";

const root = path.resolve(import.meta.dirname, "..");
const runtimePath = path.join(
  root,
  "packages",
  "platform-electron-main",
  "src",
  "boring-log-studio-preload-runtime.ts",
);
const outputPath = path.join(
  root,
  "packages",
  "platform-electron-main",
  "src",
  "boring-log-studio-preload-bundle.ts",
);

export async function buildBoringLogStudioPreloadBundleTemplate() {
  const result = await build({
    entryPoints: [runtimePath],
    bundle: true,
    platform: "browser",
    format: "cjs",
    target: "chrome142",
    external: ["electron"],
    alias: {
      "@rsrender/contracts": path.join(root, "packages", "contracts", "src", "index.ts"),
    },
    treeShaking: true,
    minify: false,
    legalComments: "none",
    charset: "utf8",
    write: false,
    logLevel: "silent",
  });
  if (result.outputFiles.length !== 1) throw new Error("STUDIO_PRELOAD_BUNDLE_OUTPUT_INVALID");
  const template = result.outputFiles[0]?.text;
  if (
    typeof template !== "string" ||
    template.match(/__RSRENDER_INITIAL_SEQUENCE_LITERAL__/gu)?.length !== 1 ||
    template.match(/__RSRENDER_STUDIO_INITIAL_SEQUENCE_LITERAL__/gu)?.length !== 1 ||
    template.match(/__RSRENDER_PUBLICATION_INITIAL_SEQUENCE_LITERAL__/gu)?.length !== 1
  ) {
    throw new Error("STUDIO_PRELOAD_BUNDLE_PLACEHOLDER_INVALID");
  }
  return template;
}

export async function generatedBoringLogStudioPreloadBundleModule() {
  const template = await buildBoringLogStudioPreloadBundleTemplate();
  return prettier.format(
    `/** Mechanically generated by tooling/generate-boring-log-studio-preload-bundle.mjs. */\nexport const boringLogStudioPreloadBundleTemplate = ${JSON.stringify(template)} as const;\n`,
    { parser: "typescript" },
  );
}

export async function verifyBoringLogStudioPreloadBundleModule() {
  const expected = await generatedBoringLogStudioPreloadBundleModule();
  try {
    return (await readFile(outputPath, "utf8")) === expected;
  } catch {
    return false;
  }
}

if (process.argv.includes("--write")) {
  await writeFile(outputPath, await generatedBoringLogStudioPreloadBundleModule(), "utf8");
} else if (!(await verifyBoringLogStudioPreloadBundleModule())) {
  throw new Error("STUDIO_PRELOAD_BUNDLE_DRIFT");
}
